  // src/components/media/MediaCenter/style.css
  var style_default37 = `:host {
    --mc-bg: #ffffff;
    --mc-border: #e2e8f0;
    --mc-grid-item-max: 180px;
    --mc-text: #1e293b;
    --mc-text-muted: #64748b;
    --mc-primary: #2563eb;
    --mc-primary-hover: #1d4ed8;
    --mc-radius: 16px;
    --mc-selected-border: var(--mc-primary);
    --mc-selected-bg: #eff6ff;

    font-family: system-ui, -apple-system, sans-serif;
    display: block;
}

/* ── Dialog ── */

dialog {
    border: none;
    border-radius: var(--mc-radius);
    padding: 0;
    width: 90vw;
    max-width: 900px;
    height: 80vh;
    box-shadow: 0 25px 60px -12px rgba(0, 0, 0, 0.25);
    overflow: hidden;
}

dialog::backdrop {
    background: rgba(0, 0, 0, 0.4);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
}

.modal-container {
    position: relative;
    display: flex;
    flex-direction: column;
    height: 100%;
    background: var(--mc-bg);
}

/* ── Header ── */

.modal-header {
    padding: 16px 20px;
    border-bottom: 1px solid var(--mc-border);
    display: flex;
    align-items: center;
    gap: 16px;
    flex-shrink: 0;
}

.modal-header h2 {
    margin: 0;
    font-size: 1rem;
    font-weight: 600;
    color: var(--mc-text);
    white-space: nowrap;
}

.toolbar {
    display: flex;
    gap: 6px;
    margin-left: auto;
}

.btn-tool {
    all: unset;
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 6px 12px;
    border-radius: 8px;
    font-size: 13px;
    font-weight: 500;
    color: var(--mc-text-muted);
    cursor: pointer;
    transition: all 0.15s;
    border: 1px solid var(--mc-border);
}

.btn-tool svg {
    width: 16px;
    height: 16px;
}

.btn-tool:hover {
    background: #f1f5f9;
    color: var(--mc-text);
}

.btn-tool-primary {
    background: var(--mc-primary);
    border-color: var(--mc-primary);
    color: #ffffff;
}

.btn-tool-primary:hover {
    background: var(--mc-primary-hover);
    color: #ffffff;
}

.btn-close {
    all: unset;
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    cursor: pointer;
    color: var(--mc-text-muted);
    font-size: 1.4rem;
    transition: all 0.15s;
    flex-shrink: 0;
}

.btn-close:hover {
    background: rgba(239, 68, 68, 0.1);
    color: #ef4444;
}

/* ── Breadcrumb ── */

.breadcrumb-bar {
    padding: 10px 20px;
    background: #f8fafc;
    border-bottom: 1px solid var(--mc-border);
    flex-shrink: 0;
}

.breadcrumb {
    display: flex;
    align-items: center;
    gap: 4px;
    font-size: 13px;
    min-height: 24px;
}

.bc-item {
    color: var(--mc-primary);
    cursor: pointer;
    padding: 2px 6px;
    border-radius: 4px;
    transition: background 0.15s;
}

.bc-item:hover {
    background: rgba(37, 99, 235, 0.08);
}

.bc-sep {
    color: var(--mc-text-muted);
    opacity: 0.4;
    user-select: none;
}

.bc-current {
    color: var(--mc-text);
    font-weight: 600;
    padding: 2px 6px;
}

/* ── Grid ── */

.media-grid {
    flex: 1;
    overflow-y: auto;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
    gap: 12px;
    padding: 20px;
    align-content: start;
    justify-items: center;
}

.media-grid > * {
    width: 100%;
    max-width: var(--mc-grid-item-max);
}

.media-grid:empty {
    display: none;
}

.media-grid:empty ~ .empty-state {
    display: flex;
}

/* ── Selected state on cards ── */

.media-grid p9r-card-media.selected {
    outline: 2px solid var(--mc-selected-border);
    outline-offset: -2px;
    border-radius: 12px;
    background: var(--mc-selected-bg);
}

/* ── Empty state ── */

.empty-state {
    display: none;
    flex: 1;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 8px;
    color: var(--mc-text-muted);
}

.empty-state svg {
    width: 48px;
    height: 48px;
    opacity: 0.3;
}

.empty-state p {
    margin: 0;
    font-size: 14px;
}

/* ── Drop overlay ── */

.drop-overlay {
    display: none;
    position: absolute;
    inset: 0;
    background: rgba(37, 99, 235, 0.08);
    border: 3px dashed var(--mc-primary);
    border-radius: var(--mc-radius);
    align-items: center;
    justify-content: center;
    z-index: 10;
    pointer-events: none;
}

.drop-overlay span {
    background: var(--mc-primary);
    color: white;
    padding: 10px 24px;
    border-radius: 10px;
    font-weight: 600;
    font-size: 14px;
}

.drop-overlay.active {
    display: flex;
}

/* ── Footer ── */

.modal-footer {
    padding: 12px 20px;
    border-top: 1px solid var(--mc-border);
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-shrink: 0;
}

.path-info {
    font-size: 12px;
    color: var(--mc-text-muted);
}

.footer-actions {
    display: flex;
    gap: 8px;
}

.btn {
    padding: 8px 16px;
    border-radius: 8px;
    cursor: pointer;
    font-weight: 500;
    font-size: 13px;
    border: none;
    transition: all 0.15s;
}

.btn-primary {
    background: var(--mc-primary);
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: var(--mc-primary-hover);
}

.btn-primary:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.btn-secondary {
    background: #f1f5f9;
    color: var(--mc-text);
}

.btn-secondary:hover {
    background: #e2e8f0;
}

/* ── New folder popover ── */

.nf-backdrop {
    display: none;
    position: absolute;
    inset: 0;
    background: rgba(0, 0, 0, 0.3);
    border-radius: var(--mc-radius);
    z-index: 100;
    align-items: center;
    justify-content: center;
}

.nf-backdrop.open {
    display: flex;
}

.nf-popover {
    background: white;
    border-radius: 12px;
    padding: 20px;
    width: 320px;
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.15);
    animation: nf-pop 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

@keyframes nf-pop {
    from { opacity: 0; transform: scale(0.95); }
    to { opacity: 1; transform: scale(1); }
}

.nf-label {
    display: block;
    font-size: 14px;
    font-weight: 600;
    margin-bottom: 10px;
    color: var(--mc-text);
}

.nf-input {
    width: 100%;
    padding: 8px 12px;
    border: 1px solid var(--mc-border);
    border-radius: 8px;
    font-size: 14px;
    box-sizing: border-box;
    outline: none;
    transition: border-color 0.15s;
}

.nf-input:focus {
    border-color: var(--mc-primary);
}

.nf-actions {
    display: flex;
    justify-content: flex-end;
    gap: 8px;
    margin-top: 14px;
}

.nf-cancel, .nf-confirm {
    padding: 6px 14px;
    border-radius: 6px;
    border: none;
    font-size: 13px;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.15s;
}

.nf-cancel {
    background: #f1f5f9;
    color: var(--mc-text);
}

.nf-cancel:hover {
    background: #e2e8f0;
}

.nf-confirm {
    background: var(--mc-primary);
    color: white;
}

.nf-confirm:hover {
    background: var(--mc-primary-hover);
}
`;

  // src/components/media/MediaCenter/MediaCenter.ts
  class MediaCenter extends U2 {
    _dialog = null;
    _grid = null;
    _btnSelect = null;
    _folder = null;
    _breadcrumb = [];
    _items = [];
    _selectedItem = null;
    _types = [];
    _dragCounter = 0;
    constructor() {
      super({
        css: style_default37,
        template: template_default37
      });
    }
    connectedCallback() {
      const s2 = this.shadowRoot;
      this._dialog = s2.querySelector("dialog");
      this._grid = s2.getElementById("grid");
      this._btnSelect = s2.getElementById("btnSelect");
      s2.getElementById("btnClose").addEventListener("click", () => this._dialog?.close());
      s2.getElementById("btnCancel").addEventListener("click", () => this._dialog?.close());
      this._dialog.addEventListener("click", (e) => {
        if (e.target === this._dialog)
          this._dialog?.close();
      });
      s2.getElementById("btnCreateFolder").addEventListener("click", () => this._openNewFolder());
      const nfBackdrop = s2.getElementById("nf-backdrop");
      const nfInput = s2.getElementById("nf-input");
      s2.getElementById("nf-cancel").addEventListener("click", () => nfBackdrop.classList.remove("open"));
      s2.getElementById("nf-confirm").addEventListener("click", () => this._createFolder(nfInput, nfBackdrop));
      nfInput.addEventListener("keydown", (e) => {
        if (e.key === "Enter")
          this._createFolder(nfInput, nfBackdrop);
        if (e.key === "Escape")
          nfBackdrop.classList.remove("open");
      });
      const fileInput = s2.getElementById("file-input");
      s2.getElementById("btnUpload").addEventListener("click", () => fileInput.click());
      fileInput.addEventListener("change", async () => {
        if (!fileInput.files?.length)
          return;
        await uploadFiles(fileInput.files, this._folder);
        fileInput.value = "";
        this._refresh();
      });
      this._btnSelect.addEventListener("click", () => this._confirmSelection());
      this._grid.addEventListener("click", (e) => {
        const card = e.target.closest("p9r-card-media");
        if (!card)
          return;
        const id = card.dataset.id;
        const type = card.dataset.type;
        if (type === "folder") {
          const folder = this._items.find((i) => i.id === id);
          this._navigateTo(id, folder?.label);
        } else {
          this._select(card, id);
        }
      });
      this._grid.addEventListener("dblclick", (e) => {
        const card = e.target.closest("p9r-card-media");
        if (!card || card.dataset.type === "folder")
          return;
        this._confirmSelection();
      });
      s2.getElementById("breadcrumb").addEventListener("click", (e) => {
        const target = e.target;
        if (!target.classList.contains("bc-item"))
          return;
        const folder = target.dataset.folder || null;
        const index = parseInt(target.dataset.index || "-1");
        this._breadcrumb = this._breadcrumb.slice(0, index + 1);
        this._navigateTo(folder);
      });
      const container = s2.querySelector(".modal-container");
      const overlay = s2.getElementById("drop-overlay");
      container.addEventListener("dragenter", (e) => {
        if (e.dataTransfer?.types.includes("Files")) {
          e.preventDefault();
          this._dragCounter++;
          overlay.classList.add("active");
        }
      });
      container.addEventListener("dragleave", () => {
        this._dragCounter--;
        if (this._dragCounter <= 0) {
          this._dragCounter = 0;
          overlay.classList.remove("active");
        }
      });
      container.addEventListener("dragover", (e) => e.preventDefault());
      container.addEventListener("drop", async (e) => {
        e.preventDefault();
        this._dragCounter = 0;
        overlay.classList.remove("active");
        if (e.dataTransfer?.files.length) {
          await uploadFiles(e.dataTransfer.files, this._folder);
          this._refresh();
        }
      });
    }
    show(types) {
      this._types = types ?? ["folder", "image", "other"];
      this._folder = null;
      this._breadcrumb = [];
      this._selectedItem = null;
      this._updateSelectButton();
      this._dialog?.showModal();
      this._refresh();
    }
    async _refresh() {
      this._items = await this._fetchItems();
      this._selectedItem = null;
      this._updateSelectButton();
      this._render();
    }
    async _fetchItems() {
      return fetchItems(this._folder, this._types);
    }
    _render() {
      renderGrid(this._grid, this._items);
      renderBreadcrumb(this.shadowRoot.getElementById("breadcrumb"), this._folder, this._breadcrumb);
      const empty4 = this.shadowRoot.getElementById("empty");
      empty4.style.display = this._items.length === 0 ? "flex" : "none";
      const pathDisplay = this.shadowRoot.getElementById("pathDisplay");
      if (this._breadcrumb.length > 0) {
        pathDisplay.textContent = this._breadcrumb.map((b) => b.label).join(" / ");
      } else {
        pathDisplay.textContent = "Root";
      }
    }
    _select(card, id) {
      this._grid.querySelectorAll("p9r-card-media.selected").forEach((el2) => el2.classList.remove("selected"));
      card.classList.add("selected");
      this._selectedItem = this._items.find((i) => i.id === id) || null;
      this._updateSelectButton();
    }
    _updateSelectButton() {
      if (this._btnSelect) {
        this._btnSelect.disabled = !this._selectedItem;
      }
    }
    _confirmSelection() {
      if (!this._selectedItem)
        return;
      const src = this._selectedItem.absoluteURL ?? "";
      this.dispatchEvent(new CustomEvent("select-item", {
        detail: { src, alt: this._selectedItem.label, mimetype: this._selectedItem.mimetype },
        bubbles: true,
        composed: true
      }));
      this._dialog?.close();
    }
    _navigateTo(folderId, label2) {
      this._folder = folderId;
      if (!folderId) {
        this._breadcrumb = [];
      } else if (label2) {
        this._breadcrumb.push({ id: folderId, label: label2 });
      }
      this._refresh();
    }
    _openNewFolder() {
      const s2 = this.shadowRoot;
      const backdrop = s2.getElementById("nf-backdrop");
      const input = s2.getElementById("nf-input");
      input.value = "";
      backdrop.classList.add("open");
      setTimeout(() => input.focus(), 50);
    }
    async _createFolder(input, backdrop) {
      const name = input.value.trim();
      if (!name)
        return;
      await createFolder(name, this._folder);
      backdrop.classList.remove("open");
      this._refresh();
    }
  }
  customElements.define("cms-media-center", MediaCenter);

